import { Column, Entity, PrimaryGeneratedColumn } from 'typeorm';

// Maps the existing `QuestionImage` table. ImageID is generated by MySQL.
@Entity({ name: 'QuestionImage' })
export class QuestionImage {
  @PrimaryGeneratedColumn({ name: 'ImageID', type: 'int' })
  imageId: number;

  @Column({ name: 'QuesID', type: 'int' })
  quesId: number;

  @Column({ name: 'ImageURL', type: 'varchar', length: 500 })
  imageUrl: string;
}
